fn normalized(text: &str) -> String {
    text.chars()
        .filter(|ch| ch.is_alphanumeric())
        .flat_map(char::to_lowercase)
        .collect()
}

fn is_palindrome(text: &str) -> bool {
    let clean = normalized(text);
    clean.chars().eq(clean.chars().rev())
}

